CREATE POLICY "cert files: read own" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'certificates' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "cert files: insert own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'certificates' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "cert files: update own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'certificates' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "cert files: delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'certificates' AND auth.uid()::text = (storage.foldername(name))[1]);